import{_ as l,C as i,c as p,o as h,aa as d,G as a}from"./chunks/framework.Cn7WEiMX.js";const r="/assets/console.XzQ9bGIy.png",k="/assets/page-preview.B8eFJ9wQ.png",t="/assets/allow-dynmap-ingress-rules.CutCXMp3.png",o="/assets/allow-dynmap-ingress-rules-2.B3TlUkNE.png",c="/assets/modified-rules.Hpnt41qf.png",g="/assets/rules-enabled.C9M_gXrL.png",F="/assets/finished-example-preview-2.CYcdjhdB.png",E=JSON.parse('{"title":"OCI（Oracle Cloud Instance）；如何启用 Dynmap","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/guides/dynmap-on-oracle-cloud-instance.md","filePath":"wiki/Dynmap/setup/guides/dynmap-on-oracle-cloud-instance.md"}'),u={name:"wiki/Dynmap/setup/guides/dynmap-on-oracle-cloud-instance.md"};function C(y,s,b,m,f,B){const e=i("NolebaseGitContributors"),n=i("NolebaseGitChangelog");return h(),p("div",null,[s[0]||(s[0]=d('<h1 id="oci-oracle-cloud-instance-如何启用-dynmap" tabindex="-1">OCI（Oracle Cloud Instance）；如何启用 Dynmap <a class="header-anchor" href="#oci-oracle-cloud-instance-如何启用-dynmap" aria-label="Permalink to &quot;OCI（Oracle Cloud Instance）；如何启用 Dynmap&quot;">​</a></h1> <p>本章节使用的是 Ubuntu ARM64 与免费的 Oracle Cloud Instance（4 核，24 GB 内存及 200 GB 存储空间）。</p> <p>在教程中，我不会详细讲述如何创建实例，也不会讲述安装和/或 Minecraft 服务器的管理方法。</p> <p><strong>教程的重点在于插件。</strong></p> <h2 id="开放端口" tabindex="-1">开放端口 <a class="header-anchor" href="#开放端口" aria-label="Permalink to &quot;开放端口&quot;">​</a></h2> <p>打开控制台左侧的菜单，找到“网络（Networking）”，选择“虚拟云网络（Virtual Cloud Networks）”。</p> <figure><img src="'+r+`" alt="" tabindex="0"><figcaption></figcaption></figure> <p>在新弹出的页面中，你应该能看到你的虚拟网络（默认以“vcn-...”开头），选中它。<br>
这之后，选择你的子网，之后选择“默认安全列表（Default Security List）”（每条只需选中一个）。</p> <p>打开的页面和这个类似：</p> <figure><img src="`+k+'" alt="" tabindex="0"><figcaption></figcaption></figure> <p>选择“添加入站规则（Add Ingress Rules）”。</p> <p>我们添加的第一个规则就是允许 Dynmap 访问：</p> <figure><img src="'+t+'" alt="" tabindex="0"><figcaption></figcaption></figure> <p>在来源类型中选择“任意（ANY）”，0.0.0.0/0 为端口号，若为 8123，则为 TCP 协议（HTTP 标准）。</p> <p>之后，我们还需要放行 Minecraft 服务器（取决于你的版本，和/或允许客户端连接到服务器的模组）：</p> <figure><img src="'+o+'" alt="" tabindex="0"><figcaption></figcaption></figure> <p>请根据你自己的需求修改这些设置。</p> <p>调整之后的规则如下：</p> <figure><img src="'+c+`" alt="" tabindex="0"><figcaption></figcaption></figure> <p>解释如下：</p> <ul><li>“无状态（Stateless）” - 我们不需要手动创建入站规则，因此无需勾选，将其交由服务器处理。若选择，我们需要新建一个允许“ANY”类型从 Dynmap 所在服务器（到任意目的地端口，因为这是不重复的随机端口）的出站规则。</li> <li>“CIDR 源（Source CIDR）” - 我们需要让“ANY”类型的连接能够进入服务器，因此需要在 CICR 部分指定 <code>0.0.0.0/0</code>。</li> <li>“源端口范围（Source Port Range）” - 由客户端定义（随机），因此需要留空。</li> <li>“目标端口范围（Destination Port Range）” - 对于这个，我们需要将目标服务的端口号填入。</li></ul> <h2 id="在实例上开放端口-ubuntu" tabindex="-1">在实例上开放端口（Ubuntu） <a class="header-anchor" href="#在实例上开放端口-ubuntu" aria-label="Permalink to &quot;在实例上开放端口（Ubuntu）&quot;">​</a></h2> <p>作为 Oracle 的首选系统，他们在这里有着更深入的讲述：
<a href="https://blogs.oracle.com/developers/post/enabling-network-traffic-to-ubuntu-images-in-oracle-cloud-infrastructure" target="_blank" rel="noreferrer">https://blogs.oracle.com/developers/post/enabling-network-traffic-to-ubuntu-images-in-oracle-cloud-infrastructure</a>，你可以浏览“防火墙托管”这部分。</p> <p>这里使用的方法是编辑名为 <code>etc/iptables/rules.v4</code> 的文件，将你的规则加入其中。</p> <div class="danger custom-block"><p class="custom-block-title">危险</p> <p>如下操作请明确承担风险，否则后果自负。</p></div> <p>有两种方法实现这个目的：</p> <h3 id="方法一-默认防火墙应用-ufw" tabindex="-1">方法一 - 默认防火墙应用：UFW <a class="header-anchor" href="#方法一-默认防火墙应用-ufw" aria-label="Permalink to &quot;方法一 - 默认防火墙应用：UFW&quot;">​</a></h3> <p>首先，可选（可以跳过初始化命令），限制任意入站连接。</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outgoing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deny</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> incoming</span></span></code></pre></div><p>现在，我们需要开放端口，首先是 SSH 访问端口（若你修改了默认的 SSH 端口（22/tcp），那么你需要自行修改命令中的参数），然后是 Dynmap 服务端口（8123/tcp），以及 Minecraft 服务器的端口（Java 与移动端）：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8123/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 25565/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 19132/udp</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">信息</p> <p>对于第一个命令，你能看到我指定了服务名称但并未指定端口，那么第一个命令效果等同于 <code>sudo ufw allow 22/tcp</code>。实际上，你可以在这里用其他服务的名称代替输入端口号，完整列表可通过这个命令浏览：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/services</span></span></code></pre></div></div> <p>添加所需规则后，应用这些新规则并启用防火墙（记得用状态命令检查内容是否正常生效）：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><figure><img src="`+g+`" alt="" tabindex="0"><figcaption></figcaption></figure> <p>这就是全部步骤了。如果你的服务器启动成功且安装了 Dynmap，你现在就可以正常打开网页地图了。😉</p> <h3 id="方法二-安装-firewall-cmd-同时禁用-ufw" tabindex="-1">方法二 - 安装 <code>firewall-cmd</code>（同时禁用 UFW） <a class="header-anchor" href="#方法二-安装-firewall-cmd-同时禁用-ufw" aria-label="Permalink to &quot;方法二 - 安装 \`firewall-cmd\`（同时禁用 UFW）&quot;">​</a></h3> <p>如果你不想使用内置的 UFW 命令，你可以安装 <code>firewall-cmd</code>。</p> <p>首先，通过如下命令安装：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewalld</span></span></code></pre></div><p>启用新服务，禁用默认服务：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewalld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewalld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span></span></code></pre></div><p>按如下示例添加所需的规则（开放端口）：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-cmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permanent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --zone=public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add-port=22/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-cmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permanent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --zone=public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add-port=8123/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-cmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permanent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --zone=public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add-port=25565/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-cmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permanent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --zone=public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add-port=19132/udp</span></span></code></pre></div><p>最后，通过如下命令重载规则集，就可以正常使用了：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">firewall-cmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reload</span></span></code></pre></div><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2> <p>最后，你就可以通过网页地图浏览服务器的内容了：</p> <p><a href="http://%E6%9C%8D%E5%8A%A1%E5%99%A8IP:Dynmap%E7%AB%AF%E5%8F%A3%E5%8F%B7" target="_blank" rel="noreferrer">http://服务器IP:Dynmap端口号</a>（端口号默认为 8123）</p> <figure><img src="`+t+'" alt="" tabindex="0"><figcaption></figcaption></figure> <figure><img src="'+F+'" alt="" tabindex="0"><figcaption></figcaption></figure> ',95)),a(e),a(n)])}const w=l(u,[["render",C]]);export{E as __pageData,w as default};
